local function beast(ctx,e)for _,tag in ipairs(ctx:card_definition(ctx:entity(e).card_id).tags)do if tag=="beast"or tag=="all"then return true end end return false end
return {api_version=1,id="DS1_175", rarity = "free",name="Timber Wolf",text="Your other Beasts have +1 Attack.",set="LEGACY",type="minion",class="hunter",cost=1,attack=1,health=2,tags={"beast"},auras={{active_zones={"board"},attack=1,targets=function(ctx,self)local r={};for _,e in ipairs(ctx:friendly_minions(self))do if e~=self and beast(ctx,e)then r[#r+1]=e end end;return r end}}}
